begin;
create table reservations.public_registration_request_members(
 id uuid primary key default extensions.gen_random_uuid(),request_id uuid not null references reservations.public_registration_requests(id) on delete cascade,member_key uuid not null,ordinal integer not null check(ordinal>=0 and ordinal<50),role text not null check(role in('primary','adult','child_paid','child_dependent')),guardian_member_key uuid,booking_type_id uuid,full_name text not null check(full_name=btrim(full_name) and char_length(full_name) between 1 and 200),phone text not null default '' check(char_length(phone)<=20),gender text check(gender is null or gender in('male','female','child')),date_of_birth date,church text not null default '' check(char_length(church)<=200),governorate text not null default '' check(char_length(governorate)<=120),city_or_village text not null default '' check(char_length(city_or_village)<=160),service_sector text not null default '' check(char_length(service_sector)<=160),service_sector_other text check(service_sector_other is null or char_length(service_sector_other)<=200),notes text check(notes is null or char_length(notes)<=4000),resolved_person_id uuid references platform.people(id) on delete restrict,booking_id uuid references reservations.bookings(id) on delete restrict,created_at timestamptz not null default statement_timestamp(),unique(request_id,member_key),unique(request_id,ordinal),unique(booking_id),check((role='child_dependent' and guardian_member_key is not null and booking_type_id is null) or(role<>'child_dependent' and guardian_member_key is null and booking_type_id is not null)),check(role not in('child_paid','child_dependent') or gender='child'));
create index public_registration_request_members_request_idx on reservations.public_registration_request_members(request_id,ordinal,id);
alter table reservations.public_registration_request_members enable row level security;alter table reservations.public_registration_request_members force row level security;revoke all on reservations.public_registration_request_members from public,anon,authenticated,service_role;
insert into reservations.public_registration_request_members(request_id,member_key,ordinal,role,booking_type_id,full_name,phone,gender,date_of_birth,church,governorate,city_or_village,service_sector,service_sector_other,notes,resolved_person_id,booking_id)
select r.id,r.id,0,'primary',r.booking_type_id,r.submitted_full_name,r.submitted_phone,r.submitted_gender,r.submitted_date_of_birth,r.submitted_church,r.submitted_governorate,r.submitted_city_or_village,r.submitted_service_sector,r.submitted_service_sector_other,r.submitted_notes,r.resolved_person_id,r.booking_id from reservations.public_registration_requests r where not exists(select 1 from reservations.public_registration_request_members m where m.request_id=r.id);

create or replace function reservations.public_registration_submit_family(p_public_id uuid,p_submit_operation_id uuid,p_tracking_secret_digest bytea,p_fingerprint_digest bytea,p_members jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare c reservations.public_registration_channels%rowtype;e reservations.events%rowtype;x reservations.public_registration_requests%rowtype;rid uuid:=extensions.gen_random_uuid();ref text;intent bytea;primary_member jsonb;m jsonb;k uuid;g uuid;role text;bt uuid;n int;ord int:=0;
begin
 if p_submit_operation_id is null or p_tracking_secret_digest is null or octet_length(p_tracking_secret_digest)<>32 or jsonb_typeof(p_members)<>'array' then raise exception 'PUBLIC_REGISTRATION_SUBMISSION_INVALID' using errcode='22023';end if;n:=jsonb_array_length(p_members);if n<1 or n>12 then raise exception 'PUBLIC_REGISTRATION_FAMILY_SIZE_INVALID' using errcode='22023';end if;primary_member:=p_members->0;if coalesce(primary_member->>'role','')<>'primary' then raise exception 'PUBLIC_REGISTRATION_PRIMARY_REQUIRED' using errcode='22023';end if;
 select * into c from reservations.public_registration_channels where public_id=p_public_id for key share;if not found or not c.enabled then raise exception 'PUBLIC_REGISTRATION_UNAVAILABLE' using errcode='P0002';end if;perform reservations_private.public_registration_rate_limit(c.id,p_fingerprint_digest,8);
 if c.registration_mode<>'approval_required' or(c.opens_at is not null and statement_timestamp()<c.opens_at)or(c.closes_at is not null and statement_timestamp()>=c.closes_at)then raise exception 'PUBLIC_REGISTRATION_CLOSED' using errcode='P0001';end if;select * into e from reservations.events where id=c.event_id for key share;if not found or e.status<>'open' then raise exception 'PUBLIC_REGISTRATION_CLOSED' using errcode='P0001';end if;
 intent:=extensions.digest(convert_to(p_members::text,'UTF8'),'sha256');perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('public-registration-submit:'||c.id::text||':'||p_submit_operation_id::text,0));select * into x from reservations.public_registration_requests where channel_id=c.id and submit_operation_id=p_submit_operation_id;if found then if x.submit_intent_digest<>intent or x.tracking_secret_digest<>p_tracking_secret_digest then raise exception 'PUBLIC_REGISTRATION_IDEMPOTENCY_CONFLICT' using errcode='40001';end if;return jsonb_build_object('reference',x.request_reference,'state',x.state,'submittedAt',x.submitted_at);end if;
 for m in select value from jsonb_array_elements(p_members) loop
  if(select array_agg(z order by z)from jsonb_object_keys(m)z)<>array['bookingTypeId','church','cityOrVillage','dateOfBirth','fullName','gender','governorate','guardianMemberKey','memberKey','notes','phone','role','serviceSector','serviceSectorOther']::text[] then raise exception 'PUBLIC_REGISTRATION_MEMBER_SHAPE_INVALID' using errcode='22023';end if;k:=(m->>'memberKey')::uuid;role:=m->>'role';g:=nullif(m->>'guardianMemberKey','')::uuid;bt:=nullif(m->>'bookingTypeId','')::uuid;
  if role not in('primary','adult','child_paid','child_dependent')or(ord=0 and role<>'primary')or(ord>0 and role='primary')then raise exception 'PUBLIC_REGISTRATION_MEMBER_ROLE_INVALID' using errcode='22023';end if;if nullif(btrim(m->>'fullName'),'')is null or nullif(m->>'dateOfBirth','')is null then raise exception 'PUBLIC_REGISTRATION_MEMBER_IDENTITY_REQUIRED' using errcode='22023';end if;
  if role='child_dependent' then if g is null or bt is not null or(m->>'gender')<>'child' then raise exception 'PUBLIC_REGISTRATION_DEPENDENT_INVALID' using errcode='22023';end if;if not exists(select 1 from jsonb_array_elements(p_members)q where(q->>'memberKey')::uuid=g and q->>'role' in('primary','adult'))then raise exception 'PUBLIC_REGISTRATION_GUARDIAN_INVALID' using errcode='22023';end if;else if g is not null or bt is null or not exists(select 1 from reservations.booking_types b where b.id=bt and b.event_id=e.id and b.active)then raise exception 'PUBLIC_REGISTRATION_BOOKING_TYPE_UNAVAILABLE' using errcode='22023';end if;end if;ord:=ord+1;
 end loop;
 ref:='PR-'||upper(substr(replace(rid::text,'-',''),1,12));insert into reservations.public_registration_requests(id,channel_id,event_id,submit_operation_id,submit_intent_digest,request_reference,tracking_secret_digest,booking_type_id,submitted_full_name,submitted_phone,submitted_gender,submitted_date_of_birth,submitted_church,submitted_governorate,submitted_city_or_village,submitted_service_sector,submitted_service_sector_other,submitted_notes)values(rid,c.id,e.id,p_submit_operation_id,intent,ref,p_tracking_secret_digest,(primary_member->>'bookingTypeId')::uuid,btrim(primary_member->>'fullName'),btrim(primary_member->>'phone'),primary_member->>'gender',(primary_member->>'dateOfBirth')::date,coalesce(primary_member->>'church',''),coalesce(primary_member->>'governorate',''),coalesce(primary_member->>'cityOrVillage',''),coalesce(primary_member->>'serviceSector',''),nullif(primary_member->>'serviceSectorOther',''),nullif(primary_member->>'notes',''));
 ord:=0;for m in select value from jsonb_array_elements(p_members) loop insert into reservations.public_registration_request_members(request_id,member_key,ordinal,role,guardian_member_key,booking_type_id,full_name,phone,gender,date_of_birth,church,governorate,city_or_village,service_sector,service_sector_other,notes)values(rid,(m->>'memberKey')::uuid,ord,m->>'role',nullif(m->>'guardianMemberKey','')::uuid,nullif(m->>'bookingTypeId','')::uuid,btrim(m->>'fullName'),btrim(coalesce(m->>'phone','')),m->>'gender',(m->>'dateOfBirth')::date,coalesce(m->>'church',''),coalesce(m->>'governorate',''),coalesce(m->>'cityOrVillage',''),coalesce(m->>'serviceSector',''),nullif(m->>'serviceSectorOther',''),nullif(m->>'notes',''));ord:=ord+1;end loop;return jsonb_build_object('reference',ref,'state','submitted','submittedAt',statement_timestamp(),'memberCount',n);
end $$;
revoke all on function reservations.public_registration_submit_family(uuid,uuid,bytea,bytea,jsonb) from public,anon,authenticated;grant execute on function reservations.public_registration_submit_family(uuid,uuid,bytea,bytea,jsonb) to service_role;
create or replace function reservations_private.public_registration_members_json(p_request_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('memberKey',m.member_key,'ordinal',m.ordinal,'role',m.role,'guardianMemberKey',m.guardian_member_key,'bookingTypeId',m.booking_type_id,'fullName',m.full_name,'phone',m.phone,'gender',m.gender,'dateOfBirth',m.date_of_birth,'church',m.church,'governorate',m.governorate,'cityOrVillage',m.city_or_village,'serviceSector',m.service_sector,'serviceSectorOther',m.service_sector_other,'notes',m.notes,'resolvedPersonId',m.resolved_person_id,'bookingId',m.booking_id))order by m.ordinal,m.id),'[]'::jsonb)from reservations.public_registration_request_members m where m.request_id=p_request_id$$;revoke all on function reservations_private.public_registration_members_json(uuid)from public,anon,authenticated,service_role;
create or replace function reservations.public_registration_status_family(p_public_id uuid,p_tracking_secret_digest bytea,p_fingerprint_digest bytea)returns jsonb language plpgsql security definer set search_path='' as $$declare b jsonb;rid uuid;begin b:=reservations.public_registration_status(p_public_id,p_tracking_secret_digest,p_fingerprint_digest);select r.id into rid from reservations.public_registration_requests r join reservations.public_registration_channels c on c.id=r.channel_id where c.public_id=p_public_id and r.tracking_secret_digest=p_tracking_secret_digest;if rid is null then raise exception 'PUBLIC_REGISTRATION_NOT_FOUND' using errcode='P0002';end if;return b||jsonb_build_object('members',reservations_private.public_registration_members_json(rid));end $$;revoke all on function reservations.public_registration_status_family(uuid,bytea,bytea)from public,anon,authenticated;grant execute on function reservations.public_registration_status_family(uuid,bytea,bytea)to service_role;
do $patch$ declare o oid:='public.public_registration_gateway(text,jsonb)'::regprocedure;d text;n text;a text:=E' elsif p_operation=\'submit\' then';i text:=E' elsif p_operation=\'status_family\' then\n  if p_args is null or jsonb_typeof(p_args)<>\'object\' or(select array_agg(k order by k)from jsonb_object_keys(p_args)k)<>array[\'fingerprintDigest\',\'publicId\',\'trackingSecretDigest\']::text[] then raise exception \'PUBLIC_REGISTRATION_ARGUMENT_INVALID\' using errcode=\'22023\';end if;return reservations.public_registration_status_family((p_args->>\'publicId\')::uuid,decode(replace(p_args->>\'trackingSecretDigest\',\'\\\\x\',\'\'),\'hex\'),decode(replace(p_args->>\'fingerprintDigest\',\'\\\\x\',\'\'),\'hex\'));\n elsif p_operation=\'submit_family\' then\n  if p_args is null or jsonb_typeof(p_args)<>\'object\' or(select array_agg(k order by k)from jsonb_object_keys(p_args)k)<>array[\'fingerprintDigest\',\'members\',\'publicId\',\'submitOperationId\',\'trackingSecretDigest\']::text[] then raise exception \'PUBLIC_REGISTRATION_ARGUMENT_INVALID\' using errcode=\'22023\';end if;return reservations.public_registration_submit_family((p_args->>\'publicId\')::uuid,(p_args->>\'submitOperationId\')::uuid,decode(replace(p_args->>\'trackingSecretDigest\',\'\\\\x\',\'\'),\'hex\'),decode(replace(p_args->>\'fingerprintDigest\',\'\\\\x\',\'\'),\'hex\'),p_args->\'members\');\n elsif p_operation=\'submit\' then';begin select pg_get_functiondef(o)into d;if position('submit_family' in d)>0 then raise exception 'PUBLIC_REGISTRATION_FAMILY_GATEWAY_ALREADY_PRESENT';end if;if position(a in d)=0 then raise exception 'PUBLIC_REGISTRATION_FAMILY_GATEWAY_ANCHOR_MISMATCH';end if;n:=replace(d,a,i);execute n;end $patch$;
commit;